import { _decorator, CCInteger, Component, Node, CCFloat, Vec3, Animation, tween, easing } from 'cc';
const { ccclass, property } = _decorator;

@ccclass('Bird')
export class bird extends Component {
    
    @property ({
        type: CCFloat,
        tooltip: 'height of bird'
    })
    public jumpHeight: number = 200;

    @property({
        type: CCFloat,
        tooltip: 'How long can they jump'
    })
    public jumpDuration: number = .3;

    public birdAnimation: Animation;
    public birdLocation: Vec3;
    public hitSomething: boolean;

    onLoad() {
        this.resetBird();
        this.birdAnimation = this.getComponent(Animation);
    }

    resetBird() {
        this.birdLocation = new Vec3(0,0,0);
        this.node.setPosition(this.birdLocation);
        this.node.setRotationFromEuler(0, 0, 0);
        this.hitSomething = false;
    }

    fly() {
        this.birdAnimation.stop();

        tween(this.node.position)
            .to(this.jumpDuration, new Vec3(this.node.position.x, this.node.position.y+this.jumpHeight,0),
            {easing:'smooth', onUpdate: (target: Vec3, ratio:number)=>{
                this.node.position = target;
            }})
            .start();

        this.birdAnimation.play();
    }
}


